using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroPontoCriticoRulesTests{[Fact] public void Ponto_critico_exige_descricao()=>FluentActions.Invoking(()=>new PontoCriticoRural(1,1,AgroPontoCriticoTipo.PONTE,"","ALTA",AgroPontoCriticoStatus.ABERTO)).Should().Throw<ArgumentException>(); [Fact] public void Ponto_critico_exige_severidade()=>FluentActions.Invoking(()=>new PontoCriticoRural(1,1,AgroPontoCriticoTipo.PONTE,"Desc","",AgroPontoCriticoStatus.ABERTO)).Should().Throw<ArgumentException>();}
